import { test } from '@playwright/test'
import { opGoto, opClick, opFill, opPress, opSeen } from '../prims'

test('@journey:suite @smoke Fill contact form twice in same tab', async ({ page }) => {
  await opGoto(page, '/contact')
  await opFill(page, 'Name', 'Test User')
  await opFill(page, 'Email', 'test@example.com')
  await opFill(page, 'Message', 'Testing form submission')
  await opClick(page, 'button', 'Send')
  await opClick(page, 'link', 'Contact')
  await opFill(page, 'Name', 'Another User')
  await opSeen(page, 'textbox', 'Name')
})
